const navToggle=document.getElementById("nav-toggle"),navMenu=document.getElementById("nav-menu");navToggle&&navMenu&&(navToggle.addEventListener("click",()=>{const e=navMenu.classList.toggle("open");navToggle.setAttribute("aria-expanded",String(e))}),navMenu.addEventListener("click",e=>{e.target.closest("a")&&(navMenu.classList.remove("open"),navToggle.setAttribute("aria-expanded","false"))}));const animated=document.querySelectorAll(".section-animate");if("IntersectionObserver"in window){const e=new IntersectionObserver(t=>{t.forEach(n=>{n.isIntersecting&&(n.target.classList.add("visible"),e.unobserve(n.target))})},{threshold:.12});animated.forEach(t=>e.observe(t))}else animated.forEach(e=>e.classList.add("visible"));const navLinks=document.querySelectorAll(".nav-link");if("IntersectionObserver"in window&&navLinks.length){const e=new IntersectionObserver(t=>{t.forEach(n=>{n.isIntersecting&&navLinks.forEach(s=>s.classList.toggle("active",s.getAttribute("href")==="#"+n.target.id))})},{rootMargin:"-40% 0px -55% 0px"});document.querySelectorAll("main section[id]").forEach(t=>e.observe(t))}const header=document.querySelector(".site-header");if(header){const e=()=>header.classList.toggle("scrolled",window.scrollY>8);window.addEventListener("scroll",e,{passive:!0}),e()}const year=document.getElementById("year");year&&(year.textContent=new Date().getFullYear()),"serviceWorker"in navigator&&window.addEventListener("load",()=>{navigator.serviceWorker.register("/sw.js").catch(()=>{})});
